import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np
    from scipy import stats

    df['month'] = pd.to_datetime(df['month'])
    counted = df[df['row_kind'] == 'counted'].copy()
    in_force = df[df['in_force_now'] == 'yes'].copy()

    # EDA on mrr across all rows
    mrr_vals = df['mrr'].dropna()
    result['eda_summary']['mrr'] = {
        'mean': float(mrr_vals.mean()),
        'std': float(mrr_vals.std()),
        'min': float(mrr_vals.min()),
        'max': float(mrr_vals.max()),
        'median': float(mrr_vals.median()),
        'count': int(mrr_vals.count())
    }
except Exception:
    pass

try:
    # Segmentation: MRR by plan, segment, country (in_force rows)
    seg_results = []
    for seg_col in ['plan', 'segment', 'country']:
        grp = in_force.groupby(seg_col)['mrr'].sum().reset_index()
        grp = grp.sort_values('mrr', ascending=False).head(10)
        seg_results.append({
            'segment_column': seg_col,
            'metric_column': 'mrr',
            'aggregation': 'sum',
            'label': None,
            'results': [{'name': str(r[seg_col]), 'value': float(r['mrr'])} for _, r in grp.iterrows()]
        })

    # Customer count by plan, segment, country (in_force)
    for seg_col in ['plan', 'segment', 'country']:
        grp = in_force.groupby(seg_col)['customer_id'].nunique().reset_index()
        grp = grp.sort_values('customer_id', ascending=False).head(10)
        seg_results.append({
            'segment_column': seg_col,
            'metric_column': 'customer_id',
            'aggregation': 'count',
            'label': None,
            'results': [{'name': str(r[seg_col]), 'value': float(r['customer_id'])} for _, r in grp.iterrows()]
        })

    # ARPA by segment (mean mrr per customer in force)
    for seg_col in ['plan', 'segment']:
        grp = in_force.groupby(seg_col).apply(
            lambda x: x.groupby('customer_id')['mrr'].last().mean()
        ).reset_index(name='arpa')
        grp = grp.sort_values('arpa', ascending=False)
        seg_results.append({
            'segment_column': seg_col,
            'metric_column': 'mrr',
            'aggregation': 'mean',
            'label': 'arpa',
            'results': [{'name': str(r[seg_col]), 'value': float(r['arpa'])} for _, r in grp.iterrows()]
        })

    result['segments'].extend(seg_results)
except Exception:
    pass

try:
    # Correlation: one row per customer (latest snapshot)
    latest = df.sort_values('month').groupby('customer_id').last().reset_index()
    numeric_cols = ['mrr']
    if len(numeric_cols) >= 1 and len(latest) >= 30:
        r_val = float(latest['mrr'].corr(latest['mrr']))
        result['correlations']['mrr__mrr'] = r_val
except Exception:
    pass

try:
    # Anomaly detection on mrr
    col = 'mrr'
    vals = df[col].dropna()
    skew = float(vals.skew())
    if abs(skew) > 2:
        shift = max(0, -vals.min())
        transformed = np.log1p(vals + shift)
    else:
        transformed = vals
        shift = 0

    q1 = float(np.percentile(transformed, 25))
    q3 = float(np.percentile(transformed, 75))
    iqr = q3 - q1
    lo = q1 - 3 * iqr
    hi = q3 + 3 * iqr

    flagged = transformed[(transformed < lo) | (transformed > hi)]
    flag_rate = len(flagged) / len(transformed)

    if flag_rate > 0.05:
        result['anomalies'].append({
            'column': col,
            'row_index': None,
            'value': None,
            'expected_range': f'{float(vals.min()):.2f}–{float(vals.max()):.2f}',
            'severity': 'low',
            'explanation': f'{col} is heavy-tailed; {flag_rate:.1%} of values fall outside the extreme IQR boundary — column skipped for individual anomaly flagging'
        })
    else:
        lo_orig = float(np.expm1(lo) - shift) if abs(skew) > 2 else float(lo)
        hi_orig = float(np.expm1(hi) - shift) if abs(skew) > 2 else float(hi)
        flagged_idx = vals.index[transformed[(transformed < lo) | (transformed > hi)].index.isin(vals.index)]
        count = 0
        for idx in flagged_idx[:25]:
            v = float(vals[idx])
            t_v = float(transformed[idx])
            if t_v > q3 + 5 * iqr or t_v < q1 - 5 * iqr:
                sev = 'critical'
            elif t_v > q3 + 4 * iqr or t_v < q1 - 4 * iqr:
                sev = 'high'
            else:
                sev = 'medium'
            result['anomalies'].append({
                'column': col,
                'row_index': int(idx),
                'value': v,
                'expected_range': f'{lo_orig:.2f}–{hi_orig:.2f}',
                'severity': sev,
                'explanation': f'{col} value {v:.2f} lies outside expected range {lo_orig:.2f}–{hi_orig:.2f}'
            })
            count += 1
            if count >= 25:
                break
except Exception:
    pass

try:
    # Trend: MRR over time (monthly snapshot sums for in_force rows by month)
    monthly_mrr = in_force.groupby('month')['mrr'].sum().sort_index()
    if len(monthly_mrr) >= 2:
        months = sorted(monthly_mrr.index)
        trend_entries = []
        for i in range(1, len(months)):
            prev_val = float(monthly_mrr[months[i-1]])
            curr_val = float(monthly_mrr[months[i]])
            if prev_val > 0:
                pct = (curr_val - prev_val) / prev_val * 100
            else:
                pct = 0.0
            direction = 'up' if pct > 0.5 else ('down' if pct < -0.5 else 'flat')
            trend_entries.append({
                'column': 'mrr',
                'period': 'MoM',
                'direction': direction,
                'pct_change': round(pct, 4),
                'segment': None
            })
        result['trends'].extend(trend_entries[-3:])
except Exception:
    pass

try:
    # Forecast: simple linear extrapolation of MRR for next 3 months
    monthly_mrr = in_force.groupby('month')['mrr'].sum().sort_index()
    if len(monthly_mrr) >= 6:
        x = np.arange(len(monthly_mrr))
        y = monthly_mrr.values
        slope, intercept, _, _, _ = stats.linregress(x, y)
        last_month = monthly_mrr.index[-1]
        forecast_pts = []
        for i in range(1, 4):
            future_month = last_month + pd.DateOffset(months=i)
            pred = float(intercept + slope * (len(monthly_mrr) - 1 + i))
            forecast_pts.append({'period': future_month.strftime('%Y-%m'), 'value': round(pred, 2)})
        result['forecast_points'].extend(forecast_pts)
except Exception:
    pass

result['assumptions'] = [
    "Segmentation and ARPA use in_force_now='yes' rows only (paying customers at latest date).",
    "MRR trend uses in_force rows grouped by month; not summed across months.",
    "Anomaly detection applied log1p transform if |skew|>2; extreme boundary is Q1-3*IQR / Q3+3*IQR.",
    "Forecast is a linear extrapolation from monthly MRR snapshots; treat as indicative only.",
    "Correlation computed on single mrr column (only numeric); no multi-column Pearson pairs available."
]

# ─── Guaranteed EDA + chart distributions + briefing (always runs) ───

try:
    _head_df = df.head(5).replace({float('nan'): None})
    result['head_preview'] = _head_df.to_dict('records')
except Exception:
    pass

try:
    result['dtypes_summary'] = {str(k): str(v) for k, v in df.dtypes.items()}
    result['non_null'] = {str(k): int(v) for k, v in df.notna().sum().items()}
    result['n_rows'] = int(len(df))
except Exception:
    pass

try:
    _miss = df.isna().mean() * 100
    result['missing_pct'] = {str(k): round(float(v), 2) for k, v in _miss.items()}
except Exception:
    pass

try:
    if 'mrr' in df.columns and pd.api.types.is_numeric_dtype(df['mrr']):
        _s = df['mrr'].dropna()
        if len(_s) > 0 and 'mrr' not in result['eda_summary']:
            result['eda_summary']['mrr'] = {
                'mean': round(float(_s.mean()), 4),
                'std': round(float(_s.std()), 4),
                'min': round(float(_s.min()), 4),
                'max': round(float(_s.max()), 4),
                'median': round(float(_s.median()), 4),
                'count': int(_s.count()),
            }
except Exception:
    pass

try:
    if 'mrr' in df.columns and pd.api.types.is_numeric_dtype(df['mrr']):
        _col_data = df['mrr'].dropna()
        if len(_col_data) >= 5:
            _n_bins = min(10, max(2, _col_data.nunique()))
            _bins = pd.cut(_col_data, bins=_n_bins)
            _vc = _bins.value_counts().sort_index()
            result['distributions']['mrr'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items() if _v > 0
            ]
except Exception:
    pass

try:
    if 'plan' in df.columns:
        _vc = df['plan'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['plan'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
    pass

try:
    if 'segment' in df.columns:
        _vc = df['segment'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['segment'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
    pass

try:
    if 'country' in df.columns:
        _vc = df['country'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['country'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
    pass
print(json.dumps(result, default=str))

